fn query_render_extent(
    xcb: &Rc<XCBConnection>,
    x_window: xproto::Window,
) -> anyhow::Result<Size<DevicePixels>> {
    let reply = get_reply(|| "X11 GetGeometry failed.", xcb.get_geometry(x_window))?;
    Ok(Size {
        width: DevicePixels(reply.width as i32),
        height: DevicePixels(reply.height as i32),
    })
}

fn resize_edge_to_moveresize(edge: ResizeEdge) -> u32 {
    match edge {
        ResizeEdge::TopLeft => 0,
        ResizeEdge::Top => 1,
        ResizeEdge::TopRight => 2,
        ResizeEdge::Right => 3,
        ResizeEdge::BottomRight => 4,
        ResizeEdge::Bottom => 5,
        ResizeEdge::BottomLeft => 6,
        ResizeEdge::Left => 7,
    }
}

/// Smallest window the application-side resize drag produces, in physical pixels.
const MIN_CLIENT_RESIZE_WIDTH: u16 = 160;
const MIN_CLIENT_RESIZE_HEIGHT: u16 = 100;

/// State of a resize drag that the application applies itself.
///
/// The `_NET_WM_MOVERESIZE` path hands the gesture to the window manager, which
/// then owns the pointer and replaces the cursor with its own edge cursor for
/// the duration of the drag. Some window managers (KWin with the default Deepin
/// `bloom` theme, for example) use a single-sided "right_side" cursor there, so
/// the double-headed resize cursor shown on hover disappears as soon as the
/// drag starts. Applying the geometry from the button press's implicit pointer
/// grab keeps the cursor that was shown at press time for the whole gesture.
#[derive(Clone, Copy)]
struct ClientResize {
    edge: ResizeEdge,
    press_x: i16,
    press_y: i16,
    origin_x: i16,
    origin_y: i16,
    width: u16,
    height: u16,
}

/// Root geometry produced by dragging `resize` by `(dx, dy)` physical pixels.
///
/// The result is `(x, y, width, height)`. Dragging the left or top edge moves
/// the origin and keeps the opposite edge pinned; the size never shrinks below
/// the minimum. Keeping this separate from the X11 calls puts the sign and
/// clamp handling for all eight directions in one place.
fn client_resize_geometry(resize: &ClientResize, dx: i32, dy: i32) -> (i32, i32, i32, i32) {
    let mut x = i32::from(resize.origin_x);
    let mut y = i32::from(resize.origin_y);
    let mut width = i32::from(resize.width);
    let mut height = i32::from(resize.height);

    let left = matches!(
        resize.edge,
        ResizeEdge::Left | ResizeEdge::TopLeft | ResizeEdge::BottomLeft
    );
    let right = matches!(
        resize.edge,
        ResizeEdge::Right | ResizeEdge::TopRight | ResizeEdge::BottomRight
    );
    let top = matches!(
        resize.edge,
        ResizeEdge::Top | ResizeEdge::TopLeft | ResizeEdge::TopRight
    );
    let bottom = matches!(
        resize.edge,
        ResizeEdge::Bottom | ResizeEdge::BottomLeft | ResizeEdge::BottomRight
    );

    if left {
        x += dx;
        width -= dx;
    } else if right {
        width += dx;
    }
    if top {
        y += dy;
        height -= dy;
    } else if bottom {
        height += dy;
    }

    let min_width = i32::from(MIN_CLIENT_RESIZE_WIDTH);
    let min_height = i32::from(MIN_CLIENT_RESIZE_HEIGHT);
    if width < min_width {
        // Keep the opposite (right) edge where it was.
        if left {
            x -= min_width - width;
        }
        width = min_width;
    }
    if height < min_height {
        // Keep the opposite (bottom) edge where it was.
        if top {
            y -= min_height - height;
        }
        height = min_height;
    }

    (x, y, width, height)
}

/// Cursor for `edge`, matching what the resize strip shows while hovered.
fn resize_edge_cursor(edge: ResizeEdge) -> CursorStyle {
    match edge {
        ResizeEdge::Top | ResizeEdge::Bottom => CursorStyle::ResizeUpDown,
        ResizeEdge::Left | ResizeEdge::Right => CursorStyle::ResizeLeftRight,
        ResizeEdge::TopLeft | ResizeEdge::BottomRight => CursorStyle::ResizeUpLeftDownRight,
        ResizeEdge::TopRight | ResizeEdge::BottomLeft => CursorStyle::ResizeUpRightDownLeft,
    }
}

#[derive(Debug)]
struct EdgeConstraints {
    top_tiled: bool,
    #[allow(dead_code)]
    top_resizable: bool,

    right_tiled: bool,
    #[allow(dead_code)]
    right_resizable: bool,

    bottom_tiled: bool,
    #[allow(dead_code)]
    bottom_resizable: bool,

    left_tiled: bool,
    #[allow(dead_code)]
    left_resizable: bool,
}

impl EdgeConstraints {
    fn from_atom(atom: u32) -> Self {
        EdgeConstraints {
            top_tiled: (atom & (1 << 0)) != 0,
            top_resizable: (atom & (1 << 1)) != 0,
            right_tiled: (atom & (1 << 2)) != 0,
            right_resizable: (atom & (1 << 3)) != 0,
            bottom_tiled: (atom & (1 << 4)) != 0,
            bottom_resizable: (atom & (1 << 5)) != 0,
            left_tiled: (atom & (1 << 6)) != 0,
            left_resizable: (atom & (1 << 7)) != 0,
        }
    }

    fn to_tiling(&self) -> Tiling {
        Tiling {
            top: self.top_tiled,
            right: self.right_tiled,
            bottom: self.bottom_tiled,
            left: self.left_tiled,
        }
    }
}

#[derive(Copy, Clone, Debug)]
struct Visual {
    id: xproto::Visualid,
    colormap: u32,
    depth: u8,
}

struct VisualSet {
    inherit: Visual,
    opaque: Option<Visual>,
    transparent: Option<Visual>,
    root: u32,
    black_pixel: u32,
}

fn find_visuals(xcb: &XCBConnection, screen_index: usize) -> VisualSet {
    let screen = &xcb.setup().roots[screen_index];
    let mut set = VisualSet {
        inherit: Visual {
            id: screen.root_visual,
            colormap: screen.default_colormap,
            depth: screen.root_depth,
        },
        opaque: None,
        transparent: None,
        root: screen.root,
        black_pixel: screen.black_pixel,
    };

    for depth_info in screen.allowed_depths.iter() {
        for visual_type in depth_info.visuals.iter() {
            let visual = Visual {
                id: visual_type.visual_id,
                colormap: 0,
                depth: depth_info.depth,
            };
            log::debug!(
                "Visual id: {}, class: {:?}, depth: {}, bits_per_value: {}, masks: 0x{:x} 0x{:x} 0x{:x}",
                visual_type.visual_id,
                visual_type.class,
                depth_info.depth,
                visual_type.bits_per_rgb_value,
                visual_type.red_mask,
                visual_type.green_mask,
                visual_type.blue_mask,
            );

            if (
                visual_type.red_mask,
                visual_type.green_mask,
                visual_type.blue_mask,
            ) != (0xFF0000, 0xFF00, 0xFF)
            {
                continue;
            }
            let color_mask = visual_type.red_mask | visual_type.green_mask | visual_type.blue_mask;
            let alpha_mask = color_mask as usize ^ ((1usize << depth_info.depth) - 1);

            if alpha_mask == 0 {
                if set.opaque.is_none() {
                    set.opaque = Some(visual);
                }
            } else {
                if set.transparent.is_none() {
                    set.transparent = Some(visual);
                }
            }
        }
    }

    set
}

#[derive(Debug, Clone, Copy)]
struct RawWindow {
    connection: *mut c_void,
    screen_id: usize,
    window_id: u32,
    visual_id: u32,
}

// Safety: The raw pointers in RawWindow point to X11 connection
// which is valid for the window's lifetime. These are used only for
// passing to wgpu which needs Send+Sync for surface creation.
unsafe impl Send for RawWindow {}
unsafe impl Sync for RawWindow {}

